export default function LabeledCheckbox({ id, label, checked, onChange }) {
  return (
    <div className="CheckboxGroup">
      <label htmlFor={id} className="CheckboxLabel">
        <input
          type="checkbox"
          id={id}
          checked={checked}
          onChange={onChange}
          className="Checkbox"
        />
        {checked && (
          <img src="/icons/check.svg" alt="" className="CheckmarkIcon" />
        )}
        <span>{label}</span>
      </label>
    </div>
  );
}
